import React, { useState } from 'react';
import { Stat, PageTitle, Field, Modal, Status, Empty } from '../../components/common';
import './FollowUpsPage.css';

export default function FollowUpsPage({leads,updateLead}) { const [filter,setFilter]=useState('All'); const items=leads.filter(l=>!['Won','Lost'].includes(l.status)).filter(l=>filter==='All'||l.next===filter); return <div className="module-page module-page--follow-ups"><PageTitle eyebrow="STAY AHEAD" title="Follow-up manager" subtitle="The next best action is always visible."/><div className="filter-row">{['All','Today','Tomorrow','Overdue','Not scheduled'].map(x=><button className={`filter-chip ${filter===x?'selected':''}`} onClick={()=>setFilter(x)} key={x}>{x}</button>)}</div><div className="followup-grid">{items.map((l,i)=><div className="panel follow-card" key={l.id}><div className="follow-card-top"><div className={`tiny-avatar av-${i%4}`}>{l.name.split(' ').map(n=>n[0]).join('').slice(0,2)}</div><Status value={l.status}/></div><h3>{l.name}</h3><p>{l.location||'Location not added'} · {l.type}</p><div className="follow-meta"><span>◷ {l.next||'Not scheduled'}</span><span>♙ {l.assigned||'Unassigned'}</span></div><div className="follow-actions"><a href={`tel:${String(l.phone).replace(/\D/g,'')}`} className="btn secondary">☎ Call</a><button className="btn primary" onClick={()=>updateLead(l.id,{next:'Tomorrow'})}>Done · reschedule</button></div></div>)}{!items.length&&<Empty title="No follow-ups in this view" desc="Try another filter or update a lead's next action."/>}</div></div>; }
